#include <cstddef>
#include <cstdint>
namespace{constexpr std::size_t D=8,L=132;void put64(std::uint8_t*o,std::size_t p,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t j=0;j<8;j++){o[p+j]=static_cast<std::uint8_t>(b&255U);b>>=8;}}bool same(const std::int64_t*a,std::size_t ar,const std::int64_t*b,std::size_t br,std::size_t w){for(std::size_t j=0;j<w;j++)if(a[ar*w+j]!=b[br*w+j])return false;return true;}}
extern "C" std::int64_t two_dimensional_string_matching(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap)noexcept{if(!in||len<6||len>L)return -1;auto rr=in[0],cc=in[1],hr=in[2],wc=in[3];if(rr<1||rr>8||cc<1||cc>8||hr<1||hr>rr||wc<1||wc>cc)return -1;auto r=static_cast<std::size_t>(rr),c=static_cast<std::size_t>(cc),h=static_cast<std::size_t>(hr),w=static_cast<std::size_t>(wc);if(len!=4+r*c+h*w)return -1;std::int64_t text[64]{},pat[64]{};std::size_t p=4;for(std::size_t i=0;i<r*c;i++){text[i]=in[p++];if(text[i]<0||text[i]>3)return -1;}for(std::size_t i=0;i<h*w;i++){pat[i]=in[p++];if(pat[i]<0||pat[i]>3)return -1;}std::int64_t prefix[D]{};for(std::size_t i=1;i<h;i++){auto q=static_cast<std::size_t>(prefix[i-1]);while(q>0&&!same(pat,i,pat,q,w))q=static_cast<std::size_t>(prefix[q-1]);if(same(pat,i,pat,q,w))++q;prefix[i]=static_cast<std::int64_t>(q);}std::uint8_t mark[D*D*D]{};for(std::size_t tr=0;tr<r;tr++)for(std::size_t col=0;col<=c-w;col++)for(std::size_t pr=0;pr<h;pr++){bool eq=true;for(std::size_t j=0;j<w;j++)if(text[tr*c+col+j]!=pat[pr*w+j])eq=false;mark[(tr*D+col)*D+pr]=eq;}std::int64_t mr[D*D]{},mc[D*D]{};std::size_t count=0;for(std::size_t col=0;col<=c-w;col++){std::size_t q=0;for(std::size_t tr=0;tr<r;tr++){while(q>0&&!mark[(tr*D+col)*D+q])q=static_cast<std::size_t>(prefix[q-1]);if(mark[(tr*D+col)*D+q])++q;if(q==h){mr[count]=static_cast<std::int64_t>(tr+1-h);mc[count]=static_cast<std::int64_t>(col);++count;q=static_cast<std::size_t>(prefix[h-1]);}}}auto bytes=8*(1+2*count);if(!out||cap<bytes)return -2;put64(out,0,static_cast<std::int64_t>(count));for(std::size_t i=0;i<count;i++){put64(out,8*(1+2*i),mr[i]);put64(out,8*(2+2*i),mc[i]);}return static_cast<std::int64_t>(bytes);}
